\begin{proposition}[The effective conductor divisor on a minimal resolution]\label{cdp:st:A.5.3}
\Uses{the hypotheses, notation and definitions stated here; \cref{cdp:st:A.2.1}; \cite[Lemma~1.1 and Corollary~1.4]{Furushima1993}}


Let $S$ be a compact reduced hypersurface in a smooth threefold, let $\eta:\coprod_i T_i\to S$ be its normalization, and let $\pi_i:Z_i\to T_i$ be the minimal resolutions. Put $h_i=\eta\pi_i$. There are canonical effective integral divisors $D_i$ on $Z_i$ with
\[
 \omega_{Z_i}(D_i)\simeq h_i^*\omega_S.
 \tag{A.25}\label{cdp:eq:A.25}
\]
The nonexceptional part of $D_i$ is exactly the divisorial conductor, with its scheme-theoretic multiplicities. When $S\subset Y$ and $H^2(Y,\Q)=0$, every $K_{Z_i}+D_i$ has rational first Chern class zero. A ruled $Z_i\to B$ with $g(B)\ge2$ then has
\[
 D_i=2C+V,
 \tag{A.26}\label{cdp:eq:A.26}
\]
where $C$ is a section and $V$ is vertical. In the case where $C$ is $\pi_i$-exceptional, $\eta^*(L|_S)|_{T_i}$ is trivial for every $L\in\Pic(Y)$.
\end{proposition}

\begin{proposition}[The unrestricted normalization target under the integral CDP hypotheses]\label{cdp:st:C4e}
\Uses{the hypotheses, notation and definitions stated here; \cref{cdp:st:C.3.1}; \cref{cdp:st:C.3.7}; \cref{cdp:st:C.3.9}; \cref{cdp:st:C.3.10}; \cref{cdp:st:C4c}; \cref{cdp:st:C4d}; \cref{cdp:st:A.5.13}; \cref{cdp:st:A.3.5}; \cref{cdp:st:A.3.4}; \cref{cdp:st:A.5.2}; \cref{cdp:st:A.3.1}; \cref{cdp:st:A.4.9}; \cref{cdp:st:A.1.1}; \cref{cdp:st:A.5.4}; \cref{cdp:st:A.5.3}; \cref{cdp:eq:C.22}; \cref{cdp:st:A.2.3}; \cref{cdp:st:A.5.12}; \cref{cdp:st:C2d}}


Let $f:Y\to\PP^1$ satisfy the integral CDP hypotheses and $c_3(Y)>0$. Then a fixed irreducible nonnormal reduced support $S$ has normalization $\eta:\widetilde S\to S$ satisfying
\[
 H^2\bigl(\widetilde S,\omega_{\widetilde S}\otimes
           \eta^*(K_Y^{-1}\otimes L)\bigr)\ne0
 \qquad\hbox{for every }L\in\Pic(Y).                  \tag{C.21}\label{cdp:eq:C.21}
\]
The assertion concerns the reduced support; no multiplicity-one conclusion is included.
\end{proposition}
